            rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
            r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
            # Complete repeated square motifs; partial edge motifs are not markers.
            if r1-r0 != c1-c0 or len(comp)!=(r1-r0+1)**2: continue
            cy=(r0+r1)//2; cx=(c0+c1)//2
            cells.append((cy,cx,grid[cy][cx],(r0,r1,c0,c1)))
    counts=Counter(v for _,_,v,_ in cells)
    if not counts: return out
    common=counts.most_common(1)[0][0]
